import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.DrWxItG4.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),o={name:"guide/introduction.md"};function i(r,e,c,l,p,d){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>This site documents every packet that the Growtopia client and a private server exchange, so you can build a server that behaves like the real one, or write your own client and <strong>speak to a server directly</strong>.</p><p>Everything here comes from three sources, and each page says which one it relies on:</p><ul><li><strong>gurotopia</strong>: the C++ server in this repository. What it sends and accepts is confirmed by its code, and by running it.</li><li><strong>GrowServer 4.0.0</strong>: a TypeScript server. It speaks the same protocol, so it&#39;s used to cross-check field names.</li><li><strong>The official Growtopia 5.60 Android client</strong> (<code>libgrowtopia.so</code>), read with static analysis. This is where the full list of client actions, the login fields and the function names come from. Nothing from it was confirmed with live traffic yet, so those pages carry <code>inferred</code> or <code>unknown</code> badges where the meaning isn&#39;t certain.</li></ul><h2 id="how-a-connection-works" tabindex="-1">How a connection works <a class="header-anchor" href="#how-a-connection-works" aria-label="Permalink to &quot;How a connection works&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>client                                     server</span></span>
<span class="line"><span>  │  HTTPS POST /growtopia/server_data.php   │   (server address, port, loginurl)</span></span>
<span class="line"><span>  │ ───────────────────────────────────────▶ │</span></span>
<span class="line"><span>  │                                          │</span></span>
<span class="line"><span>  │  ENet connect (UDP 17091)                │</span></span>
<span class="line"><span>  │ ───────────────────────────────────────▶ │</span></span>
<span class="line"><span>  │              1 SERVER_HELLO              │</span></span>
<span class="line"><span>  │ ◀─────────────────────────────────────── │</span></span>
<span class="line"><span>  │  2 GENERIC_TEXT  protocol|..ltoken|..    │</span></span>
<span class="line"><span>  │ ───────────────────────────────────────▶ │</span></span>
<span class="line"><span>  │  4 GAME_PACKET   OnSendToServer, ...     │</span></span>
<span class="line"><span>  │ ◀─────────────────────────────────────── │</span></span>
<span class="line"><span>  │  3 GAME_MESSAGE  action|enter_game ...   │</span></span>
<span class="line"><span>  │ ───────────────────────────────────────▶ │</span></span></code></pre></div><p>After the HTTPS step, everything is ENet. Every ENet packet starts with a 4-byte <a href="/gtps-guide/guide/message-types">message type</a>:</p><ul><li><strong>Text</strong> (types 2 and 3) is <code>key|value</code> lines. Every <code>action|...</code> is one of these. See <strong>Actions</strong>.</li><li><strong>Game packets</strong> (type 4) are a 56-byte binary header plus optional extra data. See <a href="/gtps-guide/guide/game-packet">Game packet header</a> and <strong>Game packets</strong>.</li><li><strong>Server function calls</strong> are game packets of type <code>0x01</code> carrying a <a href="/gtps-guide/guide/variant-list">variant list</a>. See <strong>Server functions</strong>.</li></ul><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li>To talk to your server from your own code, read <a href="/gtps-guide/guide/talk-to-server">Talk to the server</a>. It walks through a 130-line client that logs in, joins a world and chats.</li><li>To watch the official client&#39;s traffic, see <a href="/gtps-guide/guide/relay">Relay</a>.</li><li>To implement a missing feature (trading, for example), open its action pages and the server functions the client expects back.</li></ul>`,10)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
